import { AnatomicalZoneId, CorrectionStep, Muscle } from '../types/atlas';

interface MuscleBlueprint {
  id: string;
  name: string;
  latinName: string;
  zone: AnatomicalZoneId;
  origin: string;
  insertion: string;
  innervation: string;
  spinalSegment: string;
  func: string;
  patientPos: string;
  practitionerPos: string;
  testAction: string;
  pressureVector: string;
  stabilization: string;
  nlAnt: string;
  nlPost: string;
  nv: string;
  visceromotor: string;
  nutrients: string[];
  organIds: string[];
  diaphragmIds: string[];
  meridianIds: string[];
  notes: string;
  view: 'anterior' | 'posterior';
  rightX: number;
  y: number;
}

function mirrorPlateX(view: 'anterior' | 'posterior', rightX: number, lat: 'r' | 'l'): number {
  const mid = view === 'anterior' ? 250 : 773;
  const dx = Math.abs(rightX - mid);
  if (view === 'anterior') {
    return lat === 'r' ? mid - dx : mid + dx;
  }
  return lat === 'r' ? mid + dx : mid - dx;
}

function buildMuscleRecord(
  bp: MuscleBlueprint,
  suffix: '' | '-r' | '-l',
  sideLabelRu: string,
  sideLabelLa: string,
  cx: number
): Muscle {
  const steps: CorrectionStep[] = [
    {
      modality: 'Структурная / Миофасциальная',
      title: 'Позиционный релиз и работа со спайками брюшка/сухожилия',
      technique:
        'Мягкое сближение точек начала и прикрепления на фазе дыхания (техника сближения веретён / Гольджи) с последующим ретестом ММТ.',
      durationOrDose: '30–45 сек',
    },
    {
      modality: 'Рефлекторная (НЛ / НВ)',
      title: 'Активация нейролимфатических и нейрососудистых рефлексов',
      technique: `Глубокое круговое разминание НЛ-зоны (${bp.nlAnt}) и лёгкое удержание НВ-точки (${bp.nv}) до выравнивания пульсации.`,
      durationOrDose: '20–30 сек + 30 сек НВ',
    },
  ];

  return {
    id: `${bp.id}${suffix}`,
    name: sideLabelRu ? `${bp.name} (${sideLabelRu})` : bp.name,
    latinName: sideLabelLa ? `${bp.latinName} (${sideLabelLa})` : bp.latinName,
    zone: bp.zone,
    origin: bp.origin,
    insertion: bp.insertion,
    innervation: bp.innervation,
    spinalSegment: bp.spinalSegment,
    function: bp.func,
    mmt: {
      patientPosition: bp.patientPos,
      practitionerPosition: bp.practitionerPos,
      testAction: bp.testAction,
      pressureVector: bp.pressureVector,
      stabilization: bp.stabilization,
      commonErrors: [
        'Включение синергистов при недостаточной стабилизации проксимального сустава',
        'Задержка дыхания или провокация болевого паттерна вместо изометрического удержания',
      ],
      normotoniaSign: 'Плавное включение без тремора и мгновенное удержание заданного вектора',
      hypotoniaSign: 'Проскальзывание, фасцикуляции или включение компенсаторных синергистов',
    },
    reflexes: {
      neurolymphaticAnterior: bp.nlAnt,
      neurolymphaticPosterior: bp.nlPost,
      neurovascular: bp.nv,
      visceromotorLink: bp.visceromotor,
    },
    nutrients: bp.nutrients,
    organIds: bp.organIds,
    diaphragmIds: bp.diaphragmIds,
    meridianIds: bp.meridianIds,
    correctionSteps: steps,
    clinicalNotes: bp.notes,
    svgRegion: {
      view: bp.view,
      cx,
      cy: bp.y,
      labelSide: cx < (bp.view === 'anterior' ? 250 : 773) ? 'left' : 'right',
    },
  };
}

function makePaired(bp: MuscleBlueprint, gender: 'f' | 'm' = 'f'): Muscle[] {
  const ruR = gender === 'f' ? 'правая' : 'правый';
  const ruL = gender === 'f' ? 'левая' : 'левый';
  const laR = gender === 'f' ? 'dextra' : 'dexter';
  const laL = gender === 'f' ? 'sinistra' : 'sinister';
  return [
    buildMuscleRecord(bp, '-r', ruR, laR, mirrorPlateX(bp.view, bp.rightX, 'r')),
    buildMuscleRecord(bp, '-l', ruL, laL, mirrorPlateX(bp.view, bp.rightX, 'l')),
  ];
}

function makeSingle(bp: MuscleBlueprint): Muscle {
  return buildMuscleRecord(bp, '', '', '', bp.rightX);
}

